import type { AdRunnerManifest, OptimizationMode } from "../specification/types.js"; import { VALID_MODES } from "../specification/types.js";
const old: Record<string,string>={"maximum-profit":"maximum-profit is no longer valid. Use maximum-revenue.",profit:"profit is no longer valid. Use maximum-revenue.","maximum-conversion":"maximum-conversion is no longer valid. Valid modes are aesthetic, maximum-visibility, maximum-clicks, and maximum-revenue.",conversion:"conversion is no longer valid. Valid modes are aesthetic, maximum-visibility, maximum-clicks, and maximum-revenue."};
export function assertMode(value:string): asserts value is OptimizationMode { if ((old as any)[value]) throw new Error((old as any)[value]); if (!VALID_MODES.includes(value as OptimizationMode)) throw new Error(`${value} is not a valid mode. Valid modes are ${VALID_MODES.join(", ")}.`); }
export function validateManifest(manifest: AdRunnerManifest): void { const errors:string[]=[]; if(!["ad-runner/1","ad-runner/2"].includes(manifest.spec)) errors.push("spec must be ad-runner/1 or ad-runner/2"); if(!manifest.site) errors.push("site is required"); try{assertMode(manifest.mode)}catch(e){errors.push(String((e as Error).message))} const adapters=new Set(["simulated","house-ad","direct-sponsor","external-tag","exoclick","unsafe-raw-script"]); for(const [id,n] of Object.entries(manifest.networks)){ if(!n.adapter) errors.push(`network ${id} requires adapter`); if(!adapters.has(n.adapter)) errors.push(`network ${id} references missing adapter ${n.adapter}`); if(n.adapter==="unsafe-raw-script"&&!manifest.settings.allow_unsafe_scripts) errors.push(`network ${id} uses unsafe-raw-script but SITE allow_unsafe_scripts is not true`); }
 for(const [id,u] of Object.entries(manifest.units)){ if(!u.network||!manifest.networks[u.network]) errors.push(`unit ${id} references missing network ${u.network}`); const material=String(u.html??u.markup??"")+String(u.head_markup??""); if(/PASTE_|_OR_NONE\s*$/im.test(material)) errors.push(`unit ${id} contains an unresolved template value`); if(u.head_markup&&(!/^\s*(?:<meta\s+(?:(?:http-equiv|content|name|charset)\s*=\s*(?:"[^"]*"|'[^']*')\s*)+\/?>\s*)+$/i.test(String(u.head_markup)))) errors.push(`unit ${id} head_markup may contain only complete meta tags with allowed attributes`); }
 const ids=new Set<string>(); for(const p of manifest.placements){ if(ids.has(p.id)) errors.push(`placement ${p.id} is duplicated`); ids.add(p.id); if(!p.id||!p.anchor) errors.push(`placement ${p.id||"<unknown>"} requires id and anchor`); if(!p.candidates?.length) errors.push(`placement ${p.id} requires at least one candidate`); const seen=new Set<string>(); let guaranteed=0; p.candidates?.forEach((c,i)=>{ if(seen.has(c.unit)) errors.push(`placement ${p.id} has duplicate candidate unit ${c.unit}`); seen.add(c.unit); if(!manifest.units[c.unit]) errors.push(`placement ${p.id} references missing unit ${c.unit}`); if(!Number.isFinite(c.priority)) errors.push(`placement ${p.id} candidate ${c.unit} priority must be numeric`); if(!Number.isFinite(c.timeout_ms)||c.timeout_ms<50||c.timeout_ms>30000) errors.push(`placement ${p.id} candidate ${c.unit} timeout_ms must be between 50 and 30000`); if(c.guaranteed){guaranteed++; if(i!==p.candidates.length-1) errors.push(`placement ${p.id} guaranteed candidate ${c.unit} should be last`);} }); if(guaranteed>1) errors.push(`placement ${p.id} should not have more than one guaranteed candidate`); }
 if(errors.length) throw new Error(`Invalid Ad Runner manifest:\n${errors.join("\n")}`); }
